    fileLevel: project?.file ?? user?.file ?? LogLevel.debug,
    format: format == null ? null : LogPattern(format),
    timeFormat: project?.timeFormat ?? user?.timeFormat ?? defaultLogTimeFormat,
    keysFloor: debugKeys,
